import { defineStore } from 'pinia'
// import { ref } from 'vue'

export const store = defineStore('app', {
    // 状态：返回初始状态的函数
    state: () => ({
        //appId，也作为数据库的名称
        DATABASE_NAME: 'AssistingBorder App',
        //设备
        device: "phone",
        //应用数据
        App: null,
        //当前用户
        user: null,
        //高级兵种图片映射
        // profLevelList:[0,30000,75000,150000,300000],
        profLevelList: [0, 50000, 150000, 350000, 750000],
        // profLevelList:[0,2,3,6,7],
        armsMap: {
            "禁卫": "b_j",
            "重步兵": "b_z",
            "长枪兵": "b_c",
            "藤甲兵": "b_t",
            "蛮兵": "b_m",
            "白衣死士": "b_b",
            "死士": 'g_s',
            "弩兵": 'g_n',
            "解烦兵": "g_j",
            "长弓兵": 'g_c',
            "重骑兵": "q_z",
            "木牛流马": "q_m",
            "轻骑兵": "q_q",
            "铁骑兵": "q_t",
            "象兵": "q_x",
            "弓骑兵": "q_g",
            "西凉铁骑" : "q_xl"
        },
        //所有武将数据
        warriors: [],
        //所有武将的原始数据,即json文件中的数据形式
        warriorOriginDataList: [],
        //武将的索引表
        warriorIdxTable: {},
        //所有战法数据
        tactics: {
            command: [],
            active: [],
            combo: [],
            passive: [],
        },
        //该用户定义的宝物数据
        userArtifacts: [],
        //宝物数据
        artifacts: [],
        //所有已被开发战法的武将数据和战法，用于对局模块武将选择
        allWarriors: [],
        allTactics: {
            command: [],
            active: [],
            combo: [],
            passive: [],
        },
        //所有宝物，用于对局模块的宝物选择
        allArtifacts: [],
        //所有宝物的原始数据
        artifactOriginDataList: [],
        //配将队伍
        teams: [],
        //数据缓冲区
        buffer: {
            curWarrior: null,
            curTactics: null,
            curArtifact: null,
            curConfigArt: null,
            curTeam: null,
            curBattleTeam: null,

            editTactIdx: -1,
            editTeamIdx: -1,
            editTeamWarriorIdx: -1,

        },
        dirty: {
            warrior: false,
            tactics: false,

            reportHistory: false,
            battleLineup: false
        },
        //提示面板
        prompt: {
            title: "",
            type: '',
            msg: "",
            CallBack: function () { },//挂载函数
            status: false
        },
        //提示面板（双选择提示面板）
        promptOptional: {
            title: "",
            msg: "无",
            optionBtnNames: [],
            //挂载函数
            optionCallBack: [
            ],
            status: false
        },
        alertQueue: [],
        battleStorage: null,
        battle: {
            lineupList: [],//保存的阵容总表(区别battleStorage)
            visibleLineups: [],//用于展示的阵容表
            currentGroup: null,//当前选中的组
            lineupGroups: [],//阵容分组
            teams: [],
            setting: null,
            version: "默认",

            //对战结束后武将的结果
            battleResult: [
                [],
                []
            ],
            ReportHeap: [],//战报堆
            //结果统计
            Statistics: {
                allTurn: 0,
                //数据矩阵
                dataMatrices: [],
            },
            currentReport: null,
            ReportContainer: [],//战报

        }
    }),

    // 计算属性（与 Vuex 的 getters 类似）
    getters: {
        doubleCount: (state) => state.count * 2
    },

    // 方法（可同步或异步，替代 Vuex 的 actions 和 mutations）
    actions: {
        OptionalPrompt(params) {
            this.promptOptional.title = params.title || "提 示"
            this.promptOptional.msg = params.msg || '默认消息';
            this.promptOptional.optionBtnNames = params.optionBtnNames || [];
            this.promptOptional.optionCallBack = params.optionCallBack || [];
            this.promptOptional.status = true;
        },
        Prompt(params) {
            this.prompt.title = params.title || '提 示';
            this.prompt.msg = params.msg || '默认消息';
            this.prompt.type = params.type || 'info';
            this.prompt.status = true;
            this.prompt.CallBack = params.CallBack;
        },
        Alert(msg, type="normal", duration = 1500) {
            let alert_item = {
                id: Math.floor(Math.random() * 9999),
                msg: msg || "警告",
                type : type
            }
            this.alertQueue.push(alert_item)
            setTimeout(() => {
                if (this.alertQueue.length > 0) {
                    this.alertQueue.shift();
                }
            }, duration)
        },
        AutoStyle(dom) {
            dom.classList.add(this.device);
        },
       
        async fetchData() {
            const response = await fetch('/api/data')
            this.count = await response.json()
        }
    }
})

